const items = $('Get ticket messages').all();

return items.map((item, index) => {
  const allComments = item.json.comments || [];
  const conversation = [];

  // 1. EXTRACTION DU NOM DU CLIENT DEPUIS LE PREMIER MESSAGE
  // On récupère le texte du premier commentaire (celui qu'on ignorait)
  const headerText = allComments[0]?.plain_body || "";

  // On cherche "Conversation with" ou "Conversation avec" suivi du nom
  const clientNameMatch = headerText.match(/(?:Conversation with|Conversation avec)\s+(.*)/i);
  const clientName = clientNameMatch ? clientNameMatch[1].trim() : null;

  // Regex pour les messages du chat
  const msgRegex = /\(\d{2}:\d{2}:\d{2}\)\s+(.*?):\s+([\s\S]+?)(?=\n*(?:\(\d{2}:\d{2}:\d{2}\)|$))/g;

  // 2. PARCOURS DES MESSAGES (on ignore toujours le header dans la boucle)
  allComments.slice(1).forEach(commentObj => {
    const fullText = commentObj.plain_body || "";
    let match;

    while ((match = msgRegex.exec(fullText)) !== null) {
      const senderName = match[1].trim();
      const text = match[2].trim();

      // 3. LOGIQUE DE RÔLE INVERSÉE
      // Si le nom du message correspond exactement au nom extrait du header -> client
      // Sinon (si c'est Anytime ou un agent nommé) -> agent
      let role = "agent";

      if (clientName && senderName.toLowerCase() === clientName.toLowerCase()) {
        role = "client";
      }

      conversation.push({
        role: role,
        text: text
      });
    }
  });

  return {
    json: { 
      client_identified: clientName, // Pratique pour déboguer
      conversation 
    },
    pairedItem: {
      item: index
    }
  };
});

// 1. On récupère l'ID cible depuis le nœud d'options
// On utilise .first() pour s'assurer de récupérer l'ID même s'il n'y a qu'un seul item en entrée de ce nœud
const targetFieldId = $('Get id').first().json.id;

// 2. On récupère tous les items (tickets) en entrée
const items = $('New closed tickets').all();

return items.map((item, index) => {
  const customFields = item.json.custom_fields || [];
  console.log(customFields)

  // 3. On cherche dans le tableau le champ dont l'ID correspond à notre cible
  const motifField = customFields.find(f => f.id === targetFieldId);

  return {
    json: {
      // On renvoie la valeur trouvée, ou null si le champ n'existe pas dans ce ticket
      motif_de_contact: motifField ? motifField.value : null
    },
    // On conserve le lien avec l'item d'origine
    pairedItem: {
      item: index
    }
  };
});

// On récupère tous les champs (items) envoyés par l'API Zendesk
const items = $input.all();

// On cherche l'item dont le titre est exactement 'Motif de contact'
const motifField = items.find(item => item.json.title === 'Motif de contact');

// Si on le trouve, on renvoie son ID
if (motifField) {
  return {
    json: {
      id: motifField.json.id
    }
  };
} else {
  // Si on ne le trouve pas, on génère une erreur pour stopper le workflow proprement
  throw new Error("Le champ 'Motif de contact' n'a pas été trouvé dans la liste des champs Zendesk.");
}

